(5442737, 782000, 31637, '<td valign="top">Interesting project, I like the idea and the image except the wire, too bad its basic editing. 6</td>', 'Interesting project, I like the idea and the image except the wire, too bad its basic editing. 6', '2009-04-18 02:59:52.000000', NULL, 1),
(5442738, 782445, 31637, '<td valign="top">Composition fits the clever title, lighting itself very very good, although the subject isn''t anything smiting enough to score this too high, but I''ll rate the lighting quality. 7</td>', 'Composition fits the clever title, lighting itself very very good, although the subject isn''t anything smiting enough to score this too high, but I''ll rate the lighting quality. 7', '2009-04-18 03:02:29.000000', NULL, 1),
(5442739, 781717, 31637, '<td valign="top">Good analogy and a great image 7</td>', 'Good analogy and a great image 7', '2009-04-18 03:03:41.000000', NULL, 1),
(5442740, 782122, 31637, '<td valign="top">Fits the challenge for sure, the tones on the hills are contrasted enough, Im liking the abstract look to this!</td>', 'Fits the challenge for sure, the tones on the hills are contrasted enough, Im liking the abstract look to this!', '2009-04-18 03:06:04.000000', NULL, 1),
(5442742, 782034, 31637, '<td valign="top">Lovely shot, however the focus is not on the flower in the front right of the frame.</td>', 'Lovely shot, however the focus is not on the flower in the front right of the frame.', '2009-04-18 03:07:05.000000', NULL, 1),
(5442743, 781971, 31637, '<td valign="top">Nice job with the lighting, used well to add mystery; this makes me want to grow my beard again. 8</td>', 'Nice job with the lighting, used well to add mystery; this makes me want to grow my beard again. 8', '2009-04-18 03:09:24.000000', NULL, 1),
(5442745, 782414, 31637, '<td valign="top">Sweet, all you need here is some added drama with a person or other mammal.</td>', 'Sweet, all you need here is some added drama with a person or other mammal.', '2009-04-18 03:10:19.000000', NULL, 1),
(5442746, 782130, 31637, '<td valign="top">Radio-waves? What is SETI thinking!! lol...ehh, anyways, the image...very nice color, love the rich yellow matched with the auburn, perhaps one satellite like the one of the right would be enough for this. The sky is the main subject since the challenge is lighting, and the beacons themselves aren''t bright enough; 6</td>', 'Radio-waves? What is SETI thinking!! lol...ehh, anyways, the image...very nice color, love the rich yellow matched with the auburn, perhaps one satellite like the one of the right would be enough for this. The sky is the main subject since the challenge is lighting, and the beacons themselves aren''t bright enough; 6', '2009-04-18 03:12:16.000000', NULL, 1),
(5442747, 781202, 31637, '<td valign="top">Picture is 95% pleasing, but then...ouch. Sun is over-exposed- Close the aperture some more, perhaps change your center weighting or adjust the WB for your foreground. Or underexpose and use levels for the fore-ground.</td>', 'Picture is 95% pleasing, but then...ouch. Sun is over-exposed- Close the aperture some more, perhaps change your center weighting or adjust the WB for your foreground. Or underexpose and use levels for the fore-ground.', '2009-04-18 03:16:09.000000', NULL, 1),
(5442749, 782358, 31637, '<td valign="top">Flash hurts, very flat, subject is nothing to wow. Sky is nice though.</td>', 'Flash hurts, very flat, subject is nothing to wow. Sky is nice though.', '2009-04-18 03:16:43.000000', NULL, 1),
(5442751, 781765, 31637, '<td valign="top">Sweet and simple, needs a person in it.</td>', 'Sweet and simple, needs a person in it.', '2009-04-18 03:19:18.000000', NULL, 1);
